        k(r(JUMP3 + 0.28), toon={**PBH(), 'sq': [1.14, 0.84, 1.14], 'face': {**PBF, 'lid': 0.0, 'eye': 0.3, 'brow': 0.8, 'mouth': 'o'}, 'auto': 0}, toonDur=0.03, toonEase='out'),
