WAI = [-0.75, 0.0, -1.6]; CYC = [0.35, 0.0, -2.45]; BIKE = [0.42, 0.0, -2.05]; DAM = [1.25, 0.0, -1.5]; CLK = [2.05, 0.0, -3.9]
