MF = {'lid': 0.25, 'mouth': 'smile', 'brow': 0.5}
METH = lambda L=None, hl='open', **x: HAND(add(UMB, [0.0, 0.04, -0.02]), L or off(MET, RYM, 0.18, -0.22, 1.0), 'grip', hl, **x)
UMBP = lambda n, opn: P(f'parapluie{n}', 'noUmbrella', pos=UMB, ry=RYM, opts={'L': 1.15, 'r': 0.66, 'open': opn, 'colors': ['#E8463A', '#F4F1E8']})
def ROOF(n): return [P(f'terrasse{n}', 'noTerrace', pos=TER, opts={'w': 9, 'd': 8}), P(f'camera{n}', 'newsCam', pos=TVC, ry=yaw(TVC, MET))]

# 6: « La météo a annoncé : » The rooftop terrace, a TV camera on a tripod in front of her: the weather presenter's umbrella springs open with an
#    overshoot (she bobs down with it), then she presents to the camera, smiling, her free hand sweeping
D6 = st.dur('S06')
C6 = cam(0.0, F6, add(F6, [-0.05, 0.0, -0.15]), L6, L6, lens=LN6, ease='inOut')
chkc('S06', C6, {'top': add(MET, [0, 2.25, 0]), 'chin': add(MET, [0, 1.7, 0]), 'umbTop': add(UMB, [0, 1.25, 0]), 'umbL': add(UMB, [-0.66, 0.98, 0]), 'umbR': add(UMB, [0.66, 0.98, 0]), 'tv': add(TVC, [0, 1.5, 0])})
OP6 = 0.06
# (review 2: 1.2 s nearly still after the pop) the presenting sweep: her free hand sweeps out in an arc from her chest to wide and high, palm open
