          k(r(CR8 - 0.07), toon={**hk, 'sq': [0.9, 1.12, 0.9], 'face': {**f, 'lid': 0.0, 'eye': 0.35, 'brow': 1.0}}, toonDur=0.03, toonEase='out'),
