C10 = cam(0.0, F10, add(F10, [-0.02, 0.0, -0.1]), L10, L10, lens=LN10, ease='inOut')
RYBL = yaw(BLB, F10)
chkc('S10', C10, {'top': add(DOC10, [0, 2.3, 0]), 'chin': add(DOC10, [0, 1.75, 0]), 'blL': add(BLB, [-0.25, -0.17, 0]), 'blR': add(BLB, [0.25, 0.17, 0])})
