DEAD = {'pat1': {'lid': 0.35, 'mouth': 'line', 'brow': 0.1}, 'pat2': {'lid': 0.45, 'mouth': 'line', 'brow': -0.1}, 'pat3': {'lid': 0.3, 'mouth': 'line', 'brow': 0.3}}
SW10 = 0.4
SH10 = lambda p: (lambda e: HAND(e[0], e[1], 'grip', 'grip'))(box_edges(p, 0.0, side=SW10, back=0.02))
